import assert from 'node:assert/strict';
import { test } from 'node:test';
import review from '../../../scripts/lib/b3CharacterWardrobeReview.json' with { type: 'json' };
import { validateCharacterWardrobeSources } from '../../../scripts/lib/b3CharacterWardrobeChecks.mjs';
import { CHARACTER_WARDROBE_SOURCES as sources, getCharacterWardrobeLayers, getCharacterWardrobeText } from './engine/characterWardrobeSources.js';
import { CHARACTER_PROFILE_OPTIONS } from './engine/characterProfiles.js';
import { getCharacterCardOptions } from './characterCardLab.js';
const cards = getCharacterCardOptions([{ key: 'characterProfileId', options: CHARACTER_PROFILE_OPTIONS }]);
test('all 33 profiles and 134 layer maps equal the reviewed pre-move data, including order', () => {
  for (const old of review.cards) {
    const card = cards.find(x => x.id === old.id);
    assert.equal(JSON.stringify(card.sourceOption), JSON.stringify(old.option));
    assert.equal(JSON.stringify(card.defaultWardrobeLayers), JSON.stringify(old.layers));
  }
  assert.deepEqual(validateCharacterWardrobeSources(sources, CHARACTER_PROFILE_OPTIONS, cards, review), { cards: 33, layers: 134, shared: 118, reviewedDifferences: 16 });
});
test('source registry cannot be mutated and each layer consumer gets a fresh map', () => {
  assert.throws(() => { sources['character-rika'].layers.top = 'changed'; }, TypeError);
  const first = getCharacterWardrobeLayers('character-rika'); first.top = 'changed';
  assert.notEqual(getCharacterWardrobeLayers('character-rika').top, 'changed');
  assert.throws(() => getCharacterWardrobeLayers('unknown'));
  assert.throws(() => getCharacterWardrobeText('character-rika', 'identityAndBody'));
});
test('guard rejects missing owners, foreign references, changed variants and duplicated shared strings', () => {
  for (const mode of ['missing-card', 'missing-layer', 'foreign', 'text', 'literal', 'recipe', 'difference']) {
    const copy = structuredClone(sources), r = structuredClone(review);
    if (mode === 'missing-card') delete copy['character-rika'];
    if (mode === 'missing-layer') delete copy['character-rika'].layers.top;
    if (mode === 'foreign') copy['character-rika'].profile.outfit[0] = { characterId: 'character-hina', layer: 'top' };
    if (mode === 'text') copy['character-yui'].layers.shoes = 'bare feet';
    if (mode === 'literal') copy['character-rika'].profile.outfit[0] = copy['character-rika'].layers.top;
    if (mode === 'recipe') copy['character-rika'].profile.outfit.reverse();
    if (mode === 'difference') r.rows.find(x => x.characterId === 'character-yui' && x.layer === 'shoes').kind = 'shared';
    assert.throws(() => validateCharacterWardrobeSources(copy, CHARACTER_PROFILE_OPTIONS, cards, r), mode);
  }
});

import { preSavedCardsDownloadSource, preparePreSavedCardsDownloadFiles } from './savedCardsDownloadReplay.mjs';
// Test-only inverse for the narrow B3 follow-up. No production imports.
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, realpathSync, existsSync, rmSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
export const B3_ROOT = fileURLToPath(new URL('../../', import.meta.url));
export const B3_REVIEW = JSON.parse(readFileSync(new URL('./b3CharacterWardrobePatches.json', import.meta.url)));
export const B3_BASE = B3_REVIEW.baseCommit;
const hash = value => createHash('sha256').update(value).digest('hex');
export function preB3WardrobeSource(path, source) {
  source = preSavedCardsDownloadSource(path, source);
  const file = B3_REVIEW.files.find(f => f.path === path);
  if (!file || hash(source) !== file.afterHash) return source;
  assert.equal(hash(file.beforeSource), file.beforeHash, 'B3 inverse corrupt oracle');
  return Buffer.isBuffer(source) ? Buffer.from(file.beforeSource) : file.beforeSource;
}
export function restorePreB3WardrobeFiles(directory, { allowPartial = false, prepareOnly = false } = {}) {
  assert.notEqual(realpathSync(directory), realpathSync(B3_ROOT), 'B3 inverse requires isolated copy');
  assert.ok(!existsSync(join(directory, '.git')), 'B3 inverse rejects Git checkout');
  const download = preparePreSavedCardsDownloadFiles(directory);
  const empty = download;
  if (allowPartial && !B3_REVIEW.files.some(f => existsSync(join(directory, f.path))
    && hash(readFileSync(join(directory, f.path))) === f.afterHash)) return empty;
  const prepared = [], states = [];
  for (const file of B3_REVIEW.files) {
    const path = join(directory, file.path);
    if (allowPartial && !existsSync(path)) continue; // Earlier matrix fixtures copy only their own sealed paths.
    assert.ok(existsSync(path), 'B3 inverse missing source: ' + file.path);
    assert.equal(hash(file.beforeSource), file.beforeHash, 'B3 inverse corrupt oracle');
    const source = download.sources.get(file.path) ?? readFileSync(path), sha = hash(source);
    assert.ok([file.beforeHash, file.afterHash].includes(sha), 'B3 inverse rejects unknown source: ' + file.path);
    states.push(sha === file.afterHash ? 'after' : 'before');
    prepared.push([path, file.beforeSource]);
  }
  assert.ok(new Set(states).size <= 1, 'B3 inverse rejects mixed sources');
  const after = states[0] === 'after', remove = [];
  for (const [path, sha] of Object.entries(B3_REVIEW.newFiles)) {
    const full = join(directory, path);
    if (allowPartial && !existsSync(full)) continue;
    assert.equal(existsSync(full), after, 'B3 inverse missing/mixed tests: ' + path);
    if (after) { assert.equal(hash(readFileSync(full)), sha, 'B3 inverse changed test'); remove.push(full); }
  }
  if (!after) return empty;
  const plan = {
    sources: new Map([...download.sources, ...B3_REVIEW.files.filter(f => prepared.some(([path]) => path === join(directory, f.path)))
      .map(f => [f.path, Buffer.from(f.beforeSource)])]),
    apply() {
      download.apply();
      for (const [path, source] of prepared) writeFileSync(path, source);
      for (const path of remove) rmSync(path);
    },
  };
  if (!prepareOnly) plan.apply();
  return plan;
}

import {preC7CaptureHistoricalTest} from '../../../../scripts/lib/c7CaptureHistoricalTest.mjs';
import {preC7ColorPairingSource} from '../../../../scripts/lib/c7ColorPairingReplay.mjs';
import process from 'node:process';
import assert from 'node:assert/strict';
import test from 'node:test';
import {execFileSync} from 'node:child_process';
import {readFileSync,writeFileSync,mkdtempSync,mkdirSync,rmSync,symlinkSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join,dirname} from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';
import {preparePreC7NightLightingFiles} from '../../../../scripts/lib/c7NightLightingReplay.mjs';
import patch from '../../../../scripts/lib/c7NightLightingPatch.json' with {type:'json'};
import {gunzipSync} from 'node:zlib';
import * as engine from '../engine.js';
import {transitionPage1Locks} from '../../features/page1/lockTransitions.js';
import {NIGHT_SCENE,DAY_LIGHTS,fixtures,runCase} from '../../../../scripts/lib/c7NightLightingFixtures.mjs';
const root=new URL('../../../../',import.meta.url),matrix=fixtures(engine);
const before=JSON.parse(gunzipSync(readFileSync(new URL('Docs/reports/c7-night-lighting-2026-10-31/before.json.gz',root))));

test('C7 night-party random ambient excludes exactly six reviewed daylight sources',()=>{
 const seen=new Set();
 for(let i=0;i<200;i++){
  const p=runCase(engine,{name:'random '+i,input:matrix.base,seed:'c7-random:'+i}).prompt;
  assert.equal(p.selection.locationId,NIGHT_SCENE);
  assert.equal(DAY_LIGHTS.includes(p.selection.lightingId),false,p.selection.lightingId);
  seen.add(p.selection.lightingId);
 }
 const expected=matrix.menu.lightingOptions.filter(o=>o.zh!=='全無'&&!DAY_LIGHTS.includes(o.id)).map(o=>o.id);
 assert.deepEqual([...seen].sort(),expected.sort());assert.equal(seen.size,9);
});

test('C7 controls, source text, daylight/manual/none transitions and unrelated subject light stay unchanged',()=>{
 assert.deepEqual(JSON.parse(JSON.stringify(engine.getLockControls())),before.controls);
 const menu=engine.getSceneDependentOptions([],matrix.base);assert.deepEqual(menu,before.menu);assert.equal(menu.lightingOptions.length,16);
 const previous={...matrix.base,locationId:matrix.controls.find(c=>c.key==='locationId').options.find(o=>o.zh==='全無').id};
 for(const lightingId of [...DAY_LIGHTS,menu.lightingOptions.find(o=>o.zh==='全無').id]){
  const locks=transitionPage1Locks({previousLocks:{...previous,lightingId},candidateLocks:{...matrix.base,lightingId},lockControls:matrix.controls});
  assert.equal(locks.lightingId,lightingId);
  assert.equal(runCase(engine,{name:'manual',input:locks,seed:'manual'}).prompt.selection.lightingId,lightingId);
 }
 const light=matrix.controls.find(c=>c.key==='lightDirectionId').options.find(o=>o.zh==='冷白日光色溫');assert.ok(light);
 const p=runCase(engine,{name:'subject daylight temperature',input:{...matrix.base,lightDirectionId:light.id},seed:'subject'}).prompt;
 assert.equal(p.selection.lightDirectionId,light.id);
});

test('C7 custom-library compilation never contaminates the default runtime',()=>{
 for(let i=0;i<8;i++){
  const row={name:'cache isolation',input:matrix.base,seed:'cache:'+i};
  const first=runCase(engine,row);runCase(engine,row,matrix.db);runCase(engine,row,matrix.filtered);
  assert.deepEqual(runCase(engine,row),first);
 }
});

preC7CaptureHistoricalTest(import.meta.url)('C7 sealed pre-change matrix allows only the independently recorded random-pool change',()=>{
 const result=execFileSync(process.execPath,['scripts/c7_night_lighting_acceptance.mjs'],{cwd:root,encoding:'utf8',maxBuffer:1024*1024});
 const report=JSON.parse(result);assert.equal(report.record,false);assert.ok(report.cases>800);assert.ok(report.changed>0);
});

test('C7 history inverse reproduces trusted Git, rejects checkout/linked/unknown source, and is idempotent',()=>{
 assert.throws(()=>preparePreC7NightLightingFiles(fileURLToPath(root)),/isolated/);
 const dir=mkdtempSync(join(tmpdir(),'c7-inverse-test-')),path=join(dir,patch.path);
 const current=preC7ColorPairingSource(patch.path,readFileSync(new URL(patch.path,root)));
 assert.equal(createHash('sha256').update(current).digest('hex'),patch.afterHash);
 try{
  mkdirSync(dirname(path),{recursive:true});writeFileSync(path,current.toString()+'\n// unknown');
  assert.throws(()=>preparePreC7NightLightingFiles(dir),/unknown or mixed/);
  rmSync(path);symlinkSync(fileURLToPath(new URL(patch.path,root)),path);
  assert.throws(()=>preparePreC7NightLightingFiles(dir),/linked/);rmSync(path);writeFileSync(path,current);
  preparePreC7NightLightingFiles(dir).apply();
  const original=execFileSync('git',['show',patch.base+':'+patch.path],{cwd:root,maxBuffer:16*1024*1024});
  assert.deepEqual(readFileSync(path),original);preparePreC7NightLightingFiles(dir).apply();assert.deepEqual(readFileSync(path),original);
  mkdirSync(join(dir,'.git'));assert.throws(()=>preparePreC7NightLightingFiles(dir),/Git checkout/);
 }finally{rmSync(dir,{recursive:true,force:true});}
});

import assert from 'node:assert/strict';
import test from 'node:test';
import * as engine from '../engine.js';
import {fixtures,runCase,sourceFlags,referenceAllows} from '../../../../scripts/lib/c7CaptureFixtures.mjs';
const m=fixtures(engine),opts=k=>m.controls.find(x=>x.key===k).options,by=(k,id)=>opts(k).find(x=>x.id===id);
test('C7 season avoids frozen winter in random light for a flowering sunflower field',()=>{
 for(let i=0;i<80;i++){const {prompt}=runCase(engine,{name:'sunflower',input:{...m.base,locationId:m.sunflower,lightingId:''},seed:'c7-sunflower:'+i});assert.equal(prompt.selection.locationId,m.sunflower);assert.ok(!sourceFlags('ambient',by('lightingId',prompt.selection.lightingId)).includes('frozen'));}
});
test('C7 random photography style respects manual fast shutter, ambient time and subject level',()=>{
 for(const patch of [{shutterId:m.fast},{lightingId:m.night},{lightDirectionId:m.high},{lightDirectionId:m.low}])for(let i=0;i<80;i++){
  const {prompt}=runCase(engine,{name:'manual anchor',input:{...m.base,styleId:'',...patch},seed:'c7-style-anchor:'+i});
  for(const[k,v]of Object.entries(patch))assert.equal(prompt.selection[k],v);
  assert.ok(referenceAllows('style',by('styleId',prompt.selection.styleId),{ambient:by('lightingId',patch.lightingId),subject:by('lightDirectionId',patch.lightDirectionId),shutter:by('shutterId',patch.shutterId)}));
 }
});
test('C7 manual conflicts and explicitly silent companions remain selected',()=>{
 for(const shutterId of ['', 'random']){const {prompt}=runCase(engine,{name:'shutter normalization',input:{...m.base,styleId:m.slow,shutterId},seed:'c7-silent-shutter'});assert.equal(prompt.selection.shutterId,m.base.shutterId);}
 for(const patch of [{locationId:m.sunflower,lightingId:m.winter},{styleId:m.slow,shutterId:m.fast,lightDirectionId:m.high},{styleId:m.dayStyle,lightingId:m.night},{locationId:m.party,styleId:m.dayStyle}]){
  const {prompt}=runCase(engine,{name:'manual',input:{...m.base,...patch},seed:'c7-all-manual'});for(const[k,v]of Object.entries(patch))assert.equal(prompt.selection[k],v);
 }
});

test('C7 exact reviewed sources retain unknown, edited and reasonable exceptions',async()=>{
 const h=await import('./captureCompatibility.js');
 for(const [kind,key]of [['style','styleId'],['location','locationId'],['ambient','lightingId'],['subject','lightDirectionId'],['shutter','shutterId']]){
  assert.equal(m.review[kind].length,opts(key).length);
  for(const item of opts(key)){const row=m.review[kind].find(x=>x.id===item.id);assert.ok(row);assert.equal(row.en,item.en);assert.ok(row.reason);assert.deepEqual(h.reviewedCaptureFlags(kind,item),row.flags);assert.deepEqual(h.reviewedCaptureFlags(kind,{...item,en:item.en+' edited'}),[]);assert.deepEqual(h.reviewedCaptureFlags(kind,{...item,id:'unknown'}),[]);}
 }
 const find=(key,s)=>opts(key).find(x=>x.zh.includes(s));
 for(const s of ['目黑川','金色海灘','泳池露台'])assert.ok(h.seasonAllowsAmbient(find('locationId',s),by('lightingId',m.winter)));
 assert.ok(h.styleAllowsShutter(find('styleId','莎莉'),by('shutterId',m.fast)));
 assert.ok(h.styleAllowsShutter(by('styleId',m.slow),find('shutterId','1/250s')));
 for(const style of opts('styleId'))for(const item of opts('lightDirectionId'))assert.equal(h.styleAllowsSubject(style,item),referenceAllows('subject',item,{style}));
});
test('C7 reverse season and style companions keep explicit anchors and random draw order',()=>{
 for(const patch of [{locationId:'',lightingId:m.winter},{locationId:'',lightingId:m.cold},{styleId:m.slow,lightingId:'',lightDirectionId:'',shutterId:'random'},{styleId:m.dayStyle,lightingId:'',lightDirectionId:''}])for(let i=0;i<60;i++){
  const {prompt}=runCase(engine,{name:'reverse',input:{...m.base,...patch},seed:'c7-reverse:'+i});const s=prompt.selection,state={location:by('locationId',s.locationId),style:by('styleId',s.styleId)};
  for(const[k,v]of Object.entries(patch))if(v&&v!=='random')assert.equal(s[k],v);
  assert.ok(referenceAllows('ambient',by('lightingId',s.lightingId),state));assert.ok(referenceAllows('subject',by('lightDirectionId',s.lightDirectionId),state));assert.ok(referenceAllows('shutter',by('shutterId',s.shutterId),state));
 }
});
test('C7 capture inverse is pinned, isolated, idempotent and rejects unknown or linked source',async()=>{
 const {readFileSync,writeFileSync,mkdirSync,mkdtempSync,rmSync,symlinkSync}=await import('node:fs');
 const {join,dirname}=await import('node:path');const {tmpdir}=await import('node:os');const {fileURLToPath}=await import('node:url');
 const {execFileSync}=await import('node:child_process');const {createHash}=await import('node:crypto');
 const {preparePreC7CapturePairingFiles}=await import('../../../../scripts/lib/c7CapturePairingReplay.mjs');
 const patch=(await import('../../../../scripts/lib/c7CapturePairingPatches.json',{with:{type:'json'}})).default;
 const root=fileURLToPath(new URL('../../../../',import.meta.url)),dir=mkdtempSync(join(tmpdir(),'c7-capture-inverse-'));
 assert.throws(()=>preparePreC7CapturePairingFiles(root),/isolated/);
 try{
  for(const item of patch.files){assert.equal(execFileSync('git',['-C',root,'show',patch.base+':'+item.path],{encoding:'utf8',maxBuffer:16*1024*1024}),item.beforeSource);const content=readFileSync(join(root,item.path));assert.equal(createHash('sha256').update(content).digest('hex'),item.afterHash);mkdirSync(dirname(join(dir,item.path)),{recursive:true});writeFileSync(join(dir,item.path),content);}
  const[a,b]=patch.files,path=join(dir,a.path),original=readFileSync(path),untouched=readFileSync(join(dir,b.path));writeFileSync(path,'unknown');assert.throws(()=>preparePreC7CapturePairingFiles(dir),/unknown or mixed/);assert.deepEqual(readFileSync(join(dir,b.path)),untouched);rmSync(path);symlinkSync(join(root,a.path),path);assert.throws(()=>preparePreC7CapturePairingFiles(dir),/linked/);rmSync(path);writeFileSync(path,original);
  preparePreC7CapturePairingFiles(dir).apply();for(const item of patch.files)assert.equal(readFileSync(join(dir,item.path),'utf8'),item.beforeSource);preparePreC7CapturePairingFiles(dir).apply();mkdirSync(join(dir,'.git'));assert.throws(()=>preparePreC7CapturePairingFiles(dir),/Git checkout/);
 }finally{rmSync(dir,{recursive:true,force:true});}
});
